const vision=import('../vendor/vision/vision_bundle.mjs');
let model,mode='VIDEO';
self.onmessage=async({data:d})=>{try{if(d.type==='init'){const canvas=new OffscreenCanvas(1280,720);if(!canvas.getContext('webgl2'))throw Error('Worker WebGL unavailable');const {FilesetResolver,FaceLandmarker}=await vision;model=await FaceLandmarker.createFromOptions(await FilesetResolver.forVisionTasks(new URL('../vendor/vision',self.location.href).href),{baseOptions:{modelAssetPath:new URL('../vendor/vision/face_landmarker.task',self.location.href).href,delegate:'GPU'},canvas,runningMode:'VIDEO',numFaces:2,outputFaceBlendshapes:true,minFaceDetectionConfidence:.5,minFacePresenceConfidence:.5,minTrackingConfidence:.5});postMessage({type:'ready'});}else if(d.type==='detect'){if(mode!==d.mode){await model.setOptions({runningMode:d.mode});mode=d.mode;}const result=mode==='IMAGE'?model.detect(d.image):model.detectForVideo(d.image,d.time);d.image.close();postMessage({type:'result',id:d.id,time:d.time,result});}else if(d.type==='close'){model?.close();self.close();}}catch(e){d.image?.close?.();postMessage({type:'error',id:d.id,message:e.stack||e.message||String(e)});}};
